const pingCanvas = document.getElementById('ping-canvas');
        const ctx = pingCanvas.getContext('2d');
        const statusBadge = document.getElementById('main-status-badge');
        const statusDot = document.getElementById('status-dot');
        const statusText = document.getElementById('status-text');
        const startBtn = document.getElementById('start-btn');
        const btnText = document.getElementById('btn-text');
        const pingVal = document.getElementById('ping-val');
        const jitterVal = document.getElementById('jitter-val');
        const lossVal = document.getElementById('loss-val');
        const scoreVal = document.getElementById('score-val');
        const packetsSentEl = document.getElementById('packets-sent');
        const regionDisp = document.getElementById('region-disp');
        let isRunning = false;
        let pingHistory = [];
        let packetsSent = 0;
        let packetsLost = 0;
        let testInterval = null;
        let maxHistory = 60; // Increased history size for faster scroll
        // Simulating Regional Endpoints via cache-busting fetching of small assets
        // We use reliable CDNs. 
        const endpoints = {
            'auto': 'https://1.1.1.1/cdn-cgi/trace', // Cloudflare global
            'use': 'https://dynamodb.us-east-1.amazonaws.com/', // AWS US East
            'usw': 'https://dynamodb.us-west-1.amazonaws.com/', // AWS US West
            'eu': 'https://dynamodb.eu-central-1.amazonaws.com/', // AWS Europe
            'asia': 'https://dynamodb.ap-southeast-1.amazonaws.com/' // AWS Singapore
        };
        let currentEndpoint = endpoints['auto'];
        function log(msg, type = 'default') {
            const term = document.getElementById('terminal');
            const content = document.getElementById('terminal-content');
            const line = document.createElement('div');
            const time = new Date().toLocaleTimeString().split(' ')[0];
            const colorClass = type === 'success' ? 'text-sky-400' : (type === 'error' ? 'text-rose-500' : 'text-slate-400');
            line.innerHTML = `<span class="opacity-30">[${time}]</span> <span class="${colorClass}">${msg}</span>`;
            content.appendChild(line);
            term.scrollTop = term.scrollHeight;
        }
        function updateRegion() {
            const select = document.getElementById('server-select');
            const val = select.value;
            currentEndpoint = endpoints[val];
            regionDisp.innerText = val.toUpperCase();
            log(`Region switched to: ${select.options[select.selectedIndex].text}`);
            if (isRunning) stopTest(); // Restart needed
        }
        function resizeCanvas() {
            pingCanvas.width = pingCanvas.parentElement.clientWidth;
            pingCanvas.height = pingCanvas.parentElement.clientHeight;
        }
        window.addEventListener('resize', resizeCanvas);
        resizeCanvas();
        function toggleTest() {
            if (isRunning) {
                stopTest();
            } else {
                startTest();
            }
        }
        function startTest() {
            isRunning = true;
            btnText.innerText = "Stop Test";
            startBtn.classList.replace('bg-sky-500', 'bg-rose-500');
            startBtn.classList.replace('hover:bg-sky-600', 'hover:bg-rose-600');
            pingHistory = [];
            packetsSent = 0;
            packetsLost = 0;
            log("Test sequence initiated. Measuring RTT...");
            statusText.innerText = "MEASURING STABILITY...";
            statusBadge.classList.add('pulse-green');
            statusDot.style.background = "#22c55e"; // green
            // Run immediate first ping for instant feedback
            runPing();
            // Faster interval: 200ms (5Hz) to simulate game traffic
            testInterval = setInterval(runPing, 200);
        }
        function stopTest() {
            isRunning = false;
            clearInterval(testInterval);
            btnText.innerText = "Start Stability Test";
            startBtn.classList.replace('bg-rose-500', 'bg-sky-500');
            startBtn.classList.replace('hover:bg-rose-600', 'hover:bg-sky-600');
            statusBadge.classList.remove('pulse-green', 'pulse-red');
            statusText.innerText = "TEST COMPLETE";
            log("Test stopped by user.", "default");
        }
        async function runPing() {
            const start = performance.now();
            packetsSent++;
            packetsSentEl.innerText = packetsSent;
            // Stricter timeout for gaming: 800ms
            const timeoutPromise = new Promise((_, reject) =>
                setTimeout(() => reject(new Error('Timeout')), 800)
            );
            try {
                // Cache busting to ensure we hit the network
                const url = `${currentEndpoint}?t=${Date.now()}`;
                // We use 'no-cors' because we don't need the body, just the timing
                const fetchPromise = fetch(url, { mode: 'no-cors', cache: 'no-store' });
                await Promise.race([fetchPromise, timeoutPromise]);
                const end = performance.now();
                const rtt = end - start;
                pingHistory.push(rtt);
                if (pingHistory.length > maxHistory) pingHistory.shift();
                updateStats(rtt);
                drawGraph();
            } catch (error) {
                // Packet Loss logic
                packetsLost++;
                pingHistory.push(null); // Mark as lost
                if (pingHistory.length > maxHistory) pingHistory.shift();
                // log("Packet dropped (Timeout/Error).", "error"); // Reduce spam in fast mode
                updateStats(null);
                drawGraph();
            }
        }
        function updateStats(lastPing) {
            // Filter out nulls for calculation
            const validPings = pingHistory.filter(p => p !== null);
            // Current Ping
            if (lastPing) {
                pingVal.innerText = lastPing.toFixed(0);
                pingVal.style.color = lastPing < 50 ? "#38bdf8" : (lastPing < 100 ? "#fbbf24" : "#f43f5e");
            }
            // Packet Loss %
            const lossPct = ((packetsLost / packetsSent) * 100).toFixed(1);
            lossVal.innerText = `${lossPct}%`;
            lossVal.style.color = lossPct < 1 ? "#34d399" : "#f43f5e";
            // Jitter (Standard Deviation of last 60 valids)
            let jitter = 0;
            if (validPings.length > 1) {
                const recent = validPings.slice(-60);
                const mean = recent.reduce((a, b) => a + b, 0) / recent.length;
                const variance = recent.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / recent.length;
                jitter = Math.sqrt(variance);
            }
            jitterVal.innerText = jitter.toFixed(1);
            // Score Calculation
            // Base 100.
            // Ping Penalty: (Ping - 30) * 0.5 (only if > 30)
            // Jitter Penalty: Jitter * 2
            // Loss Penalty: Loss% * 50
            const avgPing = validPings.length > 0 ? validPings.reduce((a, b) => a + b, 0) / validPings.length : 0;
            const pingPenalty = Math.max(0, avgPing - 30) * 0.5;
            const jitterPenalty = jitter * 2;
            const lossPenalty = parseFloat(lossPct) * 50;
            let score = 100 - pingPenalty - jitterPenalty - lossPenalty;
            score = Math.max(0, Math.min(100, score));
            scoreVal.innerText = score.toFixed(0);
            // Update Badge Color based on score
            if (score > 85) {
                scoreVal.className = "stat-value text-emerald-400";
                statusText.innerText = "SAFE TO PLAY";
                statusDot.style.background = "#22c55e";
                statusBadge.style.borderColor = "#22c55e";
            } else if (score > 60) {
                scoreVal.className = "stat-value text-yellow-400";
                statusText.innerText = "PLAYABLE (MINOR LAG)";
                statusDot.style.background = "#facc15";
                statusBadge.style.borderColor = "#facc15";
            } else {
                scoreVal.className = "stat-value text-rose-500";
                statusText.innerText = "UNSTABLE CONNECTION";
                statusDot.style.background = "#f43f5e";
                statusBadge.style.borderColor = "#f43f5e";
                statusBadge.classList.replace('pulse-green', 'pulse-red');
            }
        }
        function drawGraph() {
            ctx.clearRect(0, 0, pingCanvas.width, pingCanvas.height);
            if (pingHistory.length < 2) return;
            const w = pingCanvas.width;
            const h = pingCanvas.height;
            const step = w / (maxHistory - 1);
            // Calculate scale dynamically but keep reasonable min/max
            // Min scale 0-100ms. If ping > 100, scale up.
            const validPings = pingHistory.filter(p => p !== null);
            const maxPing = Math.max(100, ...validPings);
            const scaleY = h / (maxPing * 1.2); // 20% headroom
            ctx.beginPath();
            ctx.lineWidth = 3;
            ctx.strokeStyle = '#38bdf8';
            ctx.lineJoin = 'round';
            let hasStarted = false;
            for (let i = 0; i < pingHistory.length; i++) {
                const x = i * step;
                const p = pingHistory[i];
                if (p === null) {
                    // Draw red vertical line for packet loss
                    ctx.save();
                    ctx.strokeStyle = '#f43f5e';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.moveTo(x, 0);
                    ctx.lineTo(x, h);
                    ctx.stroke();
                    ctx.restore();
                    // Break line continuity
                    hasStarted = false;
                    continue;
                }
                const y = h - (p * scaleY);
                if (!hasStarted) {
                    ctx.moveTo(x, y);
                    hasStarted = true;
                } else {
                    ctx.lineTo(x, y);
                }
            }
            ctx.stroke();
            // Draw Jitter Area (fill under line slightly)
            ctx.lineTo(w, h);
            ctx.lineTo(0, h);
            ctx.fillStyle = 'rgba(56, 189, 248, 0.1)';
            ctx.fill();
        }

        log("Network Diagnostic Node initialized.");
